label("$x$",(15,0),S);
draw((0,-0.2)--(0,30),Arrow);
label("$y$",(0,30),E);
draw((-14,6)--(12,6),linewidth(0.7));
label("$y=6$",(12,6),E);
draw((-1,-1)--(17,17),linewidth(0.7));
label("$y=x$",(17,17),NE);
label("$y=-x$",(-17,17),NW);
draw((1,-1)--(-17,17),linewidth(0.7));
label("$O$",O,S);
label("$P$",P,W);
draw(P--(10.2,10.2),linewidth(0.7));
